#### Phase 2: Implement Configuration Abstraction

**Step 2.1: Spring Boot Configuration Setup**

**Add Dependencies**:
```xml
<!-- pom.xml -->
<dependencies>
  <!-- Spring Cloud Config Client -->
  <dependency>
    <groupId>org.springframework.cloud</groupId>
    <artifactId>spring-cloud-starter-config</artifactId>
  </dependency>

  <!-- Spring Boot Actuator for refresh endpoint -->
  <dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-actuator</artifactId>
  </dependency>

  <!-- AWS Secrets Manager integration -->
  <dependency>
    <groupId>com.amazonaws.secretsmanager</groupId>
    <artifactId>aws-secretsmanager-jdbc</artifactId>
  </dependency>
</dependencies>
```

**Configuration Properties Class**:
```java
@Configuration
@ConfigurationProperties(prefix = "claims-api")
@RefreshScope  // Enables runtime refresh
public class ClaimsApiConfig {

    // Database configuration
    private DatabaseConfig database = new DatabaseConfig();

    // Rate limiting configuration
    private RateLimitConfig rateLimit = new RateLimitConfig();

    // Feature flags
    private FeatureFlags features = new FeatureFlags();

    // Getters and setters...

    @Data
    public static class DatabaseConfig {
        private String url;
        private String username;
        // Password loaded from AWS Secrets Manager, not directly exposed
        private int poolSize = 10;
        private Duration timeout = Duration.ofSeconds(30);
    }

    @Data
    public static class RateLimitConfig {
        private int requestsPerSecond = 100;
        private Duration window = Duration.ofSeconds(1);
    }

    @Data
    public static class FeatureFlags {
        private boolean priorAuthEnabled = false;
        private boolean enhancedValidation = false;
    }
}
```

**Application Configuration Files**:

```yaml
# src/main/resources/application.yml (bundled defaults)
claims-api:
  database:
    pool-size: 10
    timeout: 30s
  rate-limit:
    requests-per-second: 100
    window: 1s
  features:
    prior-auth-enabled: false
    enhanced-validation: false

spring:
  application:
    name: claims-api
  cloud:
    config:
      uri: ${CONFIG_SERVER_URL:http://localhost:8888}
      profile: ${SPRING_PROFILES_ACTIVE:dev}
      fail-fast: true  # Fail startup if config server unavailable

management:
  endpoints:
    web:
      exposure:
        include: health,info,refresh  # Expose refresh endpoint
```

**Step 2.2: .NET Configuration Setup**

**Add Packages**:
```xml
<!-- .csproj -->
<ItemGroup>
  <PackageReference Include="Microsoft.Extensions.Configuration.Json" Version="7.0.0" />
  <PackageReference Include="Microsoft.Extensions.Configuration.EnvironmentVariables" Version="7.0.0" />
  <PackageReference Include="AWS.Extensions.Configuration.SystemsManager" Version="3.0.0" />
  <PackageReference Include="Azure.Extensions.AspNetCore.Configuration.Secrets" Version="1.2.0" />
</ItemGroup>
```

**Configuration Setup**:
```csharp
// Program.cs
var builder = WebApplication.CreateBuilder(args);

// Add configuration sources in order of precedence (last wins)
builder.Configuration
    .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)  // Bundled defaults
    .AddJsonFile($"appsettings.{builder.Environment.EnvironmentName}.json", optional: true)  // Environment-specific
    .AddEnvironmentVariables()  // Environment variables override files
    .AddSystemsManager("/claims-api/production")  // AWS Parameter Store
    .AddAzureKeyVault(new Uri("https://keyvault.vault.azure.net/"));  // Azure Key Vault for secrets

// Bind configuration to strongly-typed options
builder.Services.Configure<DatabaseConfig>(builder.Configuration.GetSection("Database"));
builder.Services.Configure<RateLimitConfig>(builder.Configuration.GetSection("RateLimit"));

// Configuration classes
public class DatabaseConfig
{
    public string Url { get; set; }
    public string Username { get; set; }
    public string Password { get; set; }  // Loaded from Key Vault
    public int PoolSize { get; set; } = 10;
    public int TimeoutSeconds { get; set; } = 30;
}

public class RateLimitConfig
{
    public int RequestsPerSecond { get; set; } = 100;
}

// Usage with dependency injection
public class ClaimsService
{
    private readonly DatabaseConfig _dbConfig;
    private readonly IOptionsSnapshot<RateLimitConfig> _rateLimitConfig;  // Snapshot for hot reload

    public ClaimsService(
        IOptions<DatabaseConfig> dbConfig,
        IOptionsSnapshot<RateLimitConfig> rateLimitConfig)  // Use IOptionsSnapshot for refresh
    {
        _dbConfig = dbConfig.Value;
        _rateLimitConfig = rateLimitConfig;
    }

    public async Task ProcessClaim()
    {
        var currentRateLimit = _rateLimitConfig.Value.RequestsPerSecond;  // Gets latest value
        // Process claim...
    }
}
```

