### Example 2: .NET API with Azure Key Vault and App Configuration

**Context**: Provider Portal API deployed to Azure App Service requiring secure credential management and feature flag control.

**Implementation**:

```csharp
// Program.cs - Configuration setup
var builder = WebApplication.CreateBuilder(args);

// Add Azure App Configuration
var connectionString = builder.Configuration["AppConfigConnectionString"];
builder.Configuration.AddAzureAppConfiguration(options =>
{
    options.Connect(connectionString)
        .Select("ProviderPortal:*", builder.Environment.EnvironmentName)  // Environment-specific
        .ConfigureRefresh(refresh =>
        {
            // Refresh configuration every 30 seconds
            refresh.Register("ProviderPortal:RateLimit:RequestsPerSecond", refreshAll: true)
                   .SetCacheExpiration(TimeSpan.FromSeconds(30));
        })
        .UseFeatureFlags();  // Enable feature flag support
});

// Add Azure Key Vault for secrets
var keyVaultUri = new Uri(builder.Configuration["KeyVaultUri"]);
builder.Configuration.AddAzureKeyVault(keyVaultUri, new DefaultAzureCredential());

// Register configuration classes
builder.Services.Configure<DatabaseConfig>(builder.Configuration.GetSection("ProviderPortal:Database"));
builder.Services.Configure<RateLimitConfig>(builder.Configuration.GetSection("ProviderPortal:RateLimit"));

// Add Azure App Configuration middleware for refresh
builder.Services.AddAzureAppConfiguration();

var app = builder.Build();

// Enable configuration refresh middleware
app.UseAzureAppConfiguration();

app.Run();

// Configuration classes
public class DatabaseConfig
{
    public string ConnectionString { get; set; }  // Loaded from Key Vault
    public int MaxPoolSize { get; set; } = 100;
    public int CommandTimeoutSeconds { get; set; } = 30;
}

public class RateLimitConfig
{
    public int RequestsPerSecond { get; set; } = 100;
    public int WindowSeconds { get; set; } = 60;
}

// Service with configuration refresh support
public class ProviderService
{
    private readonly IOptionsSnapshot<RateLimitConfig> _rateLimitConfig;
    private readonly IOptions<DatabaseConfig> _dbConfig;

    public ProviderService(
        IOptionsSnapshot<RateLimitConfig> rateLimitConfig,  // Snapshot for refresh
        IOptions<DatabaseConfig> dbConfig)  // Static for database config
    {
        _rateLimitConfig = rateLimitConfig;
        _dbConfig = dbConfig;
    }

    public async Task<Provider> GetProvider(string providerId)
    {
        // Gets current rate limit value (refreshed automatically)
        var currentLimit = _rateLimitConfig.Value.RequestsPerSecond;

        // Use database configuration
        var connectionString = _dbConfig.Value.ConnectionString;

        // Process request...
    }
}
```

**Azure App Configuration** (via Azure Portal or CLI):
```json
