### Example 3: Node.js Lambda with AWS Parameter Store and Secrets Manager

**Context**: FHIR API Lambda function requiring OAuth configuration and database credentials.

**Implementation**:

```javascript
// config.js - Configuration loading with caching
const { SSMClient, GetParametersByPathCommand } = require('@aws-sdk/client-ssm');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class ConfigManager {
  constructor() {
    this.ssmClient = new SSMClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.secretsClient = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.configCache = null;
    this.cacheExpiry = null;
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async loadConfiguration() {
    // Return cached config if still valid
    if (this.configCache && Date.now() < this.cacheExpiry) {
      return this.configCache;
    }

    const config = {
      // Start with environment variables (lowest precedence for Lambda)
      environment: process.env.ENVIRONMENT || 'dev',
      logLevel: process.env.LOG_LEVEL || 'info',
    };

    // Load from SSM Parameter Store
    const parameterPath = `/fhir-api/${config.environment}/`;
    const parametersCommand = new GetParametersByPathCommand({
      Path: parameterPath,
      Recursive: true,
      WithDecryption: true
    });

    const parametersResponse = await this.ssmClient.send(parametersCommand);
    parametersResponse.Parameters.forEach(param => {
      const key = param.Name.replace(parameterPath, '').replace(/\//g, '.');
      this.setNestedProperty(config, key, param.Value);
    });

    // Load secrets from Secrets Manager
    const secretName = `/prod/fhir-api/database`;
    const secretCommand = new GetSecretValueCommand({ SecretId: secretName });
    const secretResponse = await this.secretsClient.send(secretCommand);
    const secrets = JSON.parse(secretResponse.SecretString);

    config.database = {
      ...config.database,
      password: secrets.password,
      username: secrets.username
    };

    // Cache configuration
    this.configCache = config;
    this.cacheExpiry = Date.now() + this.cacheTTL;

    return config;
  }

  setNestedProperty(obj, path, value) {
    const keys = path.split('.');
    let current = obj;
    for (let i = 0; i < keys.length - 1; i++) {
      if (!current[keys[i]]) current[keys[i]] = {};
      current = current[keys[i]];
    }
    current[keys[keys.length - 1]] = value;
  }
}

const configManager = new ConfigManager();
module.exports = { configManager };

// handler.js - Lambda handler using configuration
const { configManager } = require('./config');
const { Client } = require('pg');

exports.handler = async (event) => {
  // Load configuration (cached for 5 minutes)
  const config = await configManager.loadConfiguration();

  // Use configuration
  const dbClient = new Client({
    host: config.database.host,
    port: config.database.port,
    database: config.database.name,
    user: config.database.username,
    password: config.database.password,  // From Secrets Manager
    max: config.database.poolSize || 10
  });

  await dbClient.connect();

  // Process FHIR request with current rate limit
  const rateLimit = config.rateLimit.requestsPerSecond;

  // ... FHIR processing logic

  await dbClient.end();

  return {
    statusCode: 200,
    body: JSON.stringify({ message: 'Success' })
  };
};
```

**AWS Parameter Store Configuration**:
```bash
# Set parameters via AWS CLI
aws ssm put-parameter \

  --name "/fhir-api/production/database/host" \
  --value "prod-db-cluster.us-east-1.rds.amazonaws.com" \
  --type String

aws ssm put-parameter \

  --name "/fhir-api/production/rateLimit/requestsPerSecond" \
  --value "500" \
  --type String
```

**AWS Secrets Manager**:
```json
{
  "username": "fhir_api",
  "password": "<auto-generated-rotated-password>",
  "engine": "postgres",
  "host": "prod-db-cluster.us-east-1.rds.amazonaws.com",
  "port": 5432,
  "dbname": "fhir"
}
```

**Outcome**:
- Lambda cold starts load configuration from Parameter Store (cached for 5 min)
- Database credentials automatically rotated via Secrets Manager without function updates
- Configuration changes applied within cache TTL (5 minutes) without redeployment
